import axios from "axios";

const API = axios.create({ baseURL: "http://localhost:3001" }); // Replace with your backend URL

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token");
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await axios.post('http://localhost:3001/login', {
            username, 
            password
        });
        return response.data;  // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error;  // Rethrow the error so you can handle it in the component
    }
};

// Franchise APIs
export const createFranchise = (data) => API.post("/franchises", data);
export const getFranchises = () => API.get("/dashboard");
export const deleteFranchise = (id) => API.delete(`/franchises/${id}`);

// User APIs
export const createUser = (data) => API.post("/users", data);
export const updateExamData = (franchiseId, data) =>
    API.put(`/franchises/${franchiseId}/exam-data`, data);
